sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float contrast;
uniform float amount;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;

half4 main(float2 coord) {
    half4 c = image.eval(coord);
    half a = c.a;
    if (a < 0.001) {
        return half4(0.0);
    }
    half3 rgb = c.rgb / a;
    half luminance = dot(rgb, half3(0.2126, 0.7152, 0.0722));
    luminance = clamp((luminance - 0.5) * contrast + 0.5, 0.0, 1.0);
    half3 duotone = mix(color1.rgb, color2.rgb, luminance);
    rgb = mix(rgb, duotone, amount);
    return half4(rgb * a, a);
}
